/**
 * Lists the items added during the session. The list is kept in the view only, nothing is stored.
 */
@Route("")
@PageTitle("Items")
@Menu(order = 0, title = "Items")
public class ItemListView extends VerticalLayout {

    final TextField itemField;
    final Button addBtn;
    final Button clearBtn;
    final UnorderedList itemList;
    final Span itemCount;

    ItemListView() {
        itemField = new TextField("Item");
        itemField.setId("item-field");
        itemField.setPlaceholder("What do you want to track?");
        itemField.setMinWidth("15em");

        addBtn = new Button("Add", event -> addItem());
        addBtn.setId("add-button");
        addBtn.addThemeVariants(ButtonVariant.PRIMARY);

        clearBtn = new Button("Clear", event -> clearItems());
        clearBtn.setId("clear-button");

        var toolbar = new HorizontalLayout(itemField, addBtn, clearBtn);
        toolbar.setDefaultVerticalComponentAlignment(FlexComponent.Alignment.END);
        toolbar.setWrap(true);

        itemList = new UnorderedList();
        itemList.setId("item-list");

        itemCount = new Span();
        itemCount.setId("item-count");
        updateItemCount();

        add(new H1("Items"), toolbar, itemList, itemCount);
    }

    private void addItem() {
        var value = itemField.getValue();
        if (value == null || value.isBlank()) {
            itemField.setErrorMessage("Item is required");
            itemField.setInvalid(true);
            return;
        }
        itemField.setInvalid(false);
        itemList.add(new ListItem(value));
        itemField.clear();
        updateItemCount();
    }

    private void clearItems() {
        itemList.removeAll();
        updateItemCount();
    }

    private void updateItemCount() {
        itemCount.setText("Items: " + itemList.getComponentCount());
    }
}
