    @Test
    void view_starts_empty_inside_the_app_shell() {
        var view = navigate(ItemListView.class);

        assertThat($(H2.class).withText("Item Tracker").exists()).isTrue();
        assertThat($(H1.class).withText("Items").exists()).isTrue();
        assertThat(view.itemField.getLabel()).isEqualTo("Item");
        assertThat(view.itemField.getValue()).isEmpty();
        assertThat(view.addBtn.isEnabled()).isTrue();
        assertThat(view.clearBtn.isEnabled()).isTrue();
        assertThat(items(view)).isEmpty();
        assertThat(view.itemCount.getText()).isEqualTo("Items: 0");
    }

    @Test
    void add_item_appends_it_and_empties_the_field() {
        var view = navigate(ItemListView.class);

        test(view.itemField).setValue("Milk");
        test(view.addBtn).click();

        assertThat(items(view)).containsExactly("Milk");
        assertThat(view.itemField.getValue()).isEmpty();
        assertThat(view.itemField.isInvalid()).isFalse();
        assertThat(view.itemCount.getText()).isEqualTo("Items: 1");
    }

    @Test
    void items_are_appended_in_order_and_duplicates_are_kept() {
        var view = navigate(ItemListView.class);

        test(view.itemField).setValue("Milk");
        test(view.addBtn).click();
        test(view.itemField).setValue("Bread");
        test(view.addBtn).click();
        test(view.itemField).setValue("Milk");
        test(view.addBtn).click();

        assertThat(items(view)).containsExactly("Milk", "Bread", "Milk");
        assertThat(view.itemCount.getText()).isEqualTo("Items: 3");
    }

    @Test
    void blank_value_adds_nothing_and_marks_the_field_invalid() {
        var view = navigate(ItemListView.class);

        test(view.addBtn).click();

        assertThat(items(view)).isEmpty();
        assertThat(view.itemCount.getText()).isEqualTo("Items: 0");
        assertThat(view.itemField.isInvalid()).isTrue();

        test(view.itemField).setValue("   ");
        test(view.addBtn).click();

        assertThat(items(view)).isEmpty();
        assertThat(view.itemCount.getText()).isEqualTo("Items: 0");
        assertThat(view.itemField.isInvalid()).isTrue();
    }

