        test(view.itemField).setValue("Bread");
        test(view.addBtn).click();

        test(view.clearBtn).click();

        assertThat(items(view)).isEmpty();
        assertThat(view.itemCount.getText()).isEqualTo("Items: 0");

        test(view.itemField).setValue("Eggs");
        test(view.addBtn).click();

        assertThat(items(view)).containsExactly("Eggs");
        assertThat(view.itemCount.getText()).isEqualTo("Items: 1");
    }

